"""Plain-text absence notices for parents."""

from rosterkit.models import Student
from rosterkit.errors import ProjectError

ABSENT = "absent"


def _check_owner(student, marks):
    for mark in marks:
        if mark.student_id != student.student_id:
            raise ProjectError(
                f"mark for {mark.student_id} does not"
                f" belong to {student.student_id}"
            )


def _compose(student, stamps):
    names = f"{student.first_name} {student.last_name}"
    dates = ", ".join(when.isoformat() for when in stamps)
    return (
        f"{names} missed {len(stamps)} day(s) of school:"
        f" {dates}."
    )


# ---
def build_notice(student: Student, marks) -> str:
    _check_owner(student, marks)
    stamps = sorted(
        mark.day for mark in marks if mark.status == ABSENT
    )
    if not stamps:
        raise ProjectError("no absences to report")
    return _compose(student, stamps)
